var v: Node = get_tree().current_scene.find_child("OperaExplorationV1",true,false)
var probe: Node = get_tree().current_scene.get_node_or_null("OperaTiledFinalReviewProbe")
var out: Dictionary = {"snapshot":v.review_snapshot(),"save_hash":v.m.save_data.hash(),"stars":v.m.opera_stars,"pearls":v.m.pearl_count,"pause_rect":v.pause_button.get_rect(),"completed_badge_sizes":[],"failed":-1}
for badge: Sprite2D in v.badges:
	(out["completed_badge_sizes"] as Array).append(badge.texture.get_size()*badge.scale)
if probe!=null:
	out["failed"]=probe.results.get("failed",-1)
	if probe.done: probe.queue_free()
return out
